<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('guru');$pdo=db();$students=$pdo->query("SELECT id,nama_lengkap,nis,kelas,level FROM students WHERE status='aktif' AND level<9 ORDER BY kelas,nama_lengkap")->fetchAll();$studentId=(string)($_GET['student_id']??($students[0]['id']??''));$selected=null;foreach($students as $row)if($row['id']===$studentId)$selected=$row;$surahs=[];if($selected){$stmt=$pdo->prepare('SELECT nama_surah FROM surah_curriculum WHERE tahun_ajaran=? AND level=? ORDER BY urutan');$stmt->execute([ACTIVE_ACADEMIC_YEAR,$selected['level']]);$surahs=$stmt->fetchAll(PDO::FETCH_COLUMN);}$exams=$pdo->query('SELECT e.*,s.nama_lengkap FROM level_promotion_exams e JOIN students s ON s.id=e.student_id ORDER BY e.tanggal DESC LIMIT 200')->fetchAll();$pageTitle='Ujian Kenaikan Level';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Evaluasi Tahfidz</p><h1 class="page-title">Ujian Kenaikan Level</h1><p class="page-description">Pilih surat berdasarkan level asal. Status dan rata-rata dihitung otomatis.</p></div><a class="btn btn-soft" href="<?= url('guru/reports.php?type=level&student_id='.e($studentId)) ?>">Preview Rapor Resmi</a></div><section class="grid grid-2"><article class="card"><h2 class="card-title">Input Nilai Ujian</h2><form method="get" class="field" style="margin-bottom:18px"><label>Nama Peserta Didik</label><select class="select" name="student_id" onchange="this.form.submit()"><?php foreach($students as $student):?><option value="<?= e($student['id']) ?>" <?= $student['id']===$studentId?'selected':'' ?>><?= e($student['nama_lengkap'].' · '.$student['kelas'].' · '.level_name($student['level'])) ?></option><?php endforeach;?></select></form><?php if($selected):?><form action="<?= url('api/exams/index.php') ?>" method="post" data-ajax class="form-grid" data-score-group><?= csrf_field() ?><input type="hidden" name="action" value="save_level"><input type="hidden" name="student_id" value="<?= e($studentId) ?>"><input type="hidden" name="tahun_ajaran" value="<?= ACTIVE_ACADEMIC_YEAR ?>"><div class="field"><label>Tanggal</label><input class="input" type="date" name="tanggal" value="<?= date('Y-m-d') ?>"></div><div class="field"><label>Kenaikan</label><select class="select" name="level_tujuan"><?php for($level=(int)$selected['level']+1;$level<=9;$level++):?><option value="<?= $level ?>"><?= e(level_name($selected['level']).' → '.level_name($level)) ?></option><?php endfor;?></select></div><div class="field full"><label>Surat Ujian dari <?= e(level_name($selected['level'])) ?></label><select class="select" name="nama_surah" required><option value="">Pilih surat</option><?php foreach($surahs as $surah):?><option><?= e($surah) ?></option><?php endforeach;?></select></div><?php foreach(['nilai_kelancaran'=>'Kelancaran','nilai_makhraj'=>'Makhorijul Huruf','nilai_tajwid'=>'Hukum Tajwid','nilai_hafalan'=>'Sambung Ayat'] as $key=>$label):?><div class="field"><label><?= e($label) ?></label><input class="input" type="number" name="<?= $key ?>" min="0" max="100" value="80" data-score required></div><?php endforeach;?><div class="field"><label>Rata-rata</label><strong style="font-size:30px" data-average>80.00</strong></div><div class="field full"><label>Catatan Guru</label><textarea class="textarea" name="catatan_guru"></textarea></div><button class="btn btn-primary field full">Simpan Hasil Ujian</button></form><?php else:?><div class="empty"><strong>Tidak ada siswa yang dapat diuji</strong>Siswa Level 9 sudah berada di level terakhir.</div><?php endif;?></article><article class="card"><h2 class="card-title">Ketentuan Otomatis</h2><div class="alert alert-info">Rata-rata empat komponen minimal 75 dinyatakan <strong>Lulus</strong>. Level siswa hanya berubah jika lulus.</div><div class="compact-list"><div class="compact-item"><span>Level yang didukung</span><strong>1–9</strong></div><div class="compact-item"><span>Sumber surat</span><strong>Data Surat</strong></div><div class="compact-item"><span>Tahun ajaran</span><strong><?= ACTIVE_ACADEMIC_YEAR ?></strong></div><div class="compact-item"><span>Pencatatan audit</span><strong>Aktif</strong></div></div></article></section><section class="card" style="margin-top:20px"><h2 class="card-title">Riwayat Ujian</h2><div class="table-wrap"><table class="table"><thead><tr><th>Tanggal</th><th>Siswa</th><th>Kenaikan</th><th>Surat</th><th>Rata-rata</th><th>Status</th><th>Catatan</th></tr></thead><tbody><?php foreach($exams as $exam):?><tr><td><?= e(format_date_id($exam['tanggal'])) ?></td><td class="name"><?= e($exam['nama_lengkap']) ?></td><td><?= e(level_name($exam['level_asal']).' → '.level_name($exam['level_tujuan'])) ?></td><td><?= e($exam['nama_surah']) ?></td><td><strong><?= e((string)$exam['nilai_rata_rata']) ?></strong></td><td><span class="badge <?= $exam['status']==='Lulus'?'badge-green':'badge-yellow' ?>"><?= e($exam['status']) ?></span></td><td><?= e($exam['catatan_guru']) ?></td></tr><?php endforeach;?></tbody></table></div></section><?php require ROOT_PATH.'/includes/footer.php';?>

